from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict

class Settings(BaseSettings):
    """
    Application settings loaded from environment variables.
    Uses Pydantic for validation and type coercion.
    """
    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    SERVICE_NAME: str = Field("SwarmOS Health Monitor", description="Name of the microservice.")
    SERVICE_VERSION: str = Field("1.0.0", description="Version of the microservice.")
    LOG_LEVEL: str = Field("INFO", description="Logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL).")
    SIMULATE_FAILURE: bool = Field(False, description="If true, the health check will intentionally fail.")

    @property
    def is_debug(self) -> bool:
        return self.LOG_LEVEL.upper() == "DEBUG"

